    /*
     * For languages where the UI text is not fully localized
     * yet, we deliberately keep a readable English fallback
     * rather than pretending that an incorrect translation is
     * authoritative.
     */
    private val translations =
        mapOf(
            "en" to en,
            "hi" to hi,
            "bn" to bn,
            "te" to te,
            "mr" to mr,
            "ta" to ta,
            "gu" to gu,
            "kn" to kn,
            "ml" to ml,
            "pa" to pa,
            "ur" to ur,
            "or" to or,
            "as" to asLang,
            "sa" to sa,
            "ne" to ne,
            "kok" to kok,
            "mai" to mai,
            "ks" to ks,
            "sd" to sd,
            "doi" to doi,
            "mni" to mni,
            "brx" to brx,
            "sat" to sat,
            "es" to es,
            "fr" to fr,
            "de" to de,
            "ar" to ar,
            "zh" to zh,
            "ja" to ja,
            "ko" to ko,
            "pt" to pt,
            "it" to it,
            "ru" to ru,
            "tr" to tr
        )

    fun value(
        language: String,
        key: String
    ): String {

        val selected =
            translations[language]
                ?.get(key)

        if (
            !selected.isNullOrBlank()
        ) {
            return selected
        }

        return en[key] ?: key
    }
}



